CREATE TABLE `outreach_queue` (`id` int AUTO_INCREMENT NOT NULL, `leadId` varchar(128) NOT NULL, `company` varchar(255) NOT NULL, `jobTitle` varchar(255) NOT NULL, `recipientEmail` varchar(320), `jobUrl` text, `resumeUrl` text, `coverLetter` text, `resumeText` text, `status` enum('pending','approved','rejected','sent','archived') NOT NULL DEFAULT 'pending', `generatedAt` timestamp NOT NULL DEFAULT (now()), `approvedAt` timestamp, `sentAt` timestamp, `createdAt` timestamp NOT NULL DEFAULT (now()), `updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT `outreach_queue_id` PRIMARY KEY(`id`));
CREATE TABLE `outreach_touches` (`id` int AUTO_INCREMENT NOT NULL, `queueId` int NOT NULL, `touchNumber` int NOT NULL, `delayDays` int NOT NULL, `scheduledFor` timestamp, `status` enum('scheduled','sent','skipped','cancelled') NOT NULL DEFAULT 'scheduled', `sentAt` timestamp, `createdAt` timestamp NOT NULL DEFAULT (now()), CONSTRAINT `outreach_touches_id` PRIMARY KEY(`id`));
CREATE TABLE `outreach_events` (`id` int AUTO_INCREMENT NOT NULL, `queueId` int NOT NULL, `eventType` enum('generated','approved','rejected','sent','opened','replied','unsubscribed','archived','send_blocked') NOT NULL, `metadata` text, `occurredAt` timestamp NOT NULL DEFAULT (now()), CONSTRAINT `outreach_events_id` PRIMARY KEY(`id`));
CREATE TABLE `outreach_opt_outs` (`id` int AUTO_INCREMENT NOT NULL, `email` varchar(320) NOT NULL, `token` varchar(128) NOT NULL, `reason` varchar(255), `createdAt` timestamp NOT NULL DEFAULT (now()), CONSTRAINT `outreach_opt_outs_id` PRIMARY KEY(`id`), CONSTRAINT `outreach_opt_outs_email_unique` UNIQUE(`email`), CONSTRAINT `outreach_opt_outs_token_unique` UNIQUE(`token`));
